WithName(
  ref{thisTable#aux_WaterfallDRE}.Filter(ref{columns/c-NJBJ7BHGOo#Ordem;column;loop} = ref{columns/c-NJBJ7BHGOo#Ordem;row;relative} - 1).First(),
  ref{opaque:variable:grid-EHjR2RLET8:::true:false:Prev},
  If(
    ref{columns/c-NJBJ7BHGOo#Ordem;row;relative} = 1,
    0,
    If(
      ref{columns/c-umHpeu1b5r#Totais;row;relative}.IsNotBlank(),
      0,
      If(
        ref{opaque:variable:grid-EHjR2RLET8:::true:false:Prev}.ref{columns/c-umHpeu1b5r#Totais;column;loop}.IsNotBlank(),
        /* Caso a linha ANTERIOR seja um TOTAL */
        ref{opaque:variable:grid-EHjR2RLET8:::true:false:Prev}.ref{columns/c-umHpeu1b5r#Totais;column;loop}
        - ref{columns/c-SvVMAC8KjG#Saída;row;relative}
        - ref{columns/c-LkeG6GDxQM#Provisões;row;relative},

        /* Demais casos: segue a lógica de “degrau” normal */
        ref{opaque:variable:grid-EHjR2RLET8:::true:false:Prev}.ref{columns/c-cs-H4HAc3D#_;column;loop}
        - ref{columns/c-SvVMAC8KjG#Saída;row;relative}
        +ref{opaque:variable:grid-EHjR2RLET8:::true:false:Prev}.ref{columns/c-eAuzrJGnWH#Entrada;column;loop}.Sum()
        + If(ref{columns/c-NJBJ7BHGOo#Ordem;row;relative} <= 15, ref{opaque:variable:grid-EHjR2RLET8:::true:false:Prev}.ref{columns/c-LkeG6GDxQM#Provisões;column;loop}, ref{columns/c-LkeG6GDxQM#Provisões;row;relative}*(-1))
      )
    )
  )
)

WithName(
  RegexReplace(ref{columns/c-5Jgezs2B3o#funil_Contato;row;relative}, [literal], [literal]),
  ref{vars/NumeroLimpo;loop},
  If(
    ref{vars/NumeroLimpo;loop}.IsBlank(),
    [literal],
    If(
      ref{vars/NumeroLimpo;loop}.Len() < 8,
      [literal],
      WithName(
         /* =====================================================
           ETAPA 2 — GARANTE DDI
           ===================================================== */
        If(
          ref{vars/NumeroLimpo;loop}.StartsWith([literal]),
          ref{vars/NumeroLimpo;loop},
          Concatenate([literal], ref{vars/NumeroLimpo;loop})
        ),
        ref{vars/NumeroComDDI;loop},
        WithName(
           /* =====================================================
             ETAPA 3 — REMOVE DDI
             ===================================================== */
          ref{vars/NumeroComDDI;loop}.Right(ref{vars/NumeroComDDI;loop}.Len() - 2),
          ref{vars/NumeroSemDDI;loop},
               WithName(
               /* =====================================================
                 ETAPA 4 — GARANTE DDD (SÓ SE NÃO EXISTIR)
                 ===================================================== */
              If(
                ref{vars/NumeroSemDDI;loop}.Len() = 9,
                Concatenate([literal], ref{vars/NumeroSemDDI;loop}),
                ref{vars/NumeroSemDDI;loop}
              ),
              ref{vars/NumeroComDDD;loop},
              WithName(
                 /* =====================================================
                   ETAPA 5 — INSERE 9º DÍGITO (COM REGRAS)
                   ===================================================== */
                If(
                  AND(
                    ref{vars/NumeroComDDD;loop}.Len() = 10,
                    ref{vars/NumeroComDDD;loop}.Mid(3, 1) >= [literal],
                    ref{vars/NumeroComDDD;loop}.Mid(3, 1) <= [literal]
                  ),
                  Concatenate(
                    ref{vars/NumeroComDDD;loop}.Left(2), [literal], ref{vars/NumeroComDDD;loop}.Right(8)
                  ),
                  ref{vars/NumeroComDDD;loop}
                ),
                ref{vars/NumeroCelularCompleto;loop},
                 /* =====================================================
                   ETAPA 6 — VALIDA FINAL
                   ===================================================== */ IF(
                  OR(
                    AND(
                      ref{vars/NumeroCelularCompleto;loop}.Len() = 11,
                      ref{vars/NumeroCelularCompleto;loop}.Mid(3, 1) = [literal]
                    ),
                    ref{vars/NumeroCelularCompleto;loop}.Len() = 10
                  ),
                  Concatenate([literal], ref{vars/NumeroCelularCompleto;loop}),
                  [literal]
                )
              )

          )
        )
      )
    )
  )
)

