formulas.formula:
Ceiling(
  ref{tables/grid-1g3KP98jSe#db_lavMetaMensal}
    .FormulaMap(
      Max(
        0,
        (
          Min(
            ref{tables/grid-1g3KP98jSe/columns/c-CFX_J47Yxu#Mes;column;loop}.EndOfMonth(0),
            Date(ref{controls/ctrl-LN4RzfVKRh#MesDash}.Year(), 1, 1) + Days((ref{columns/c-IgAxTZty-u#Semana;row;relative} - 1) * 7) + Days(6)
          )
          -
          Max(
            Date(Year(ref{tables/grid-1g3KP98jSe/columns/c-CFX_J47Yxu#Mes;column;loop}), Month(ref{tables/grid-1g3KP98jSe/columns/c-CFX_J47Yxu#Mes;column;loop}), 1),
            Date(ref{controls/ctrl-LN4RzfVKRh#MesDash}.Year(), 1, 1) + Days((ref{columns/c-IgAxTZty-u#Semana;row;relative} - 1) * 7)
          )
          + Days(1)
        ) / Days(1)
      )
      *
      (
        ref{opaque:variable:grid-1g3KP98jSe:::true:false:CurrentValue}.ref{tables/grid-1g3KP98jSe/columns/c-ciRfdjXlGY#Meta;column;loop}
        /
        (
          (ref{tables/grid-1g3KP98jSe/columns/c-CFX_J47Yxu#Mes;column;loop}.EndOfMonth(0) - Date(Year(ref{tables/grid-1g3KP98jSe/columns/c-CFX_J47Yxu#Mes;column;loop}), Month(ref{tables/grid-1g3KP98jSe/columns/c-CFX_J47Yxu#Mes;column;loop}), 1)) / Days(1)
          + 1
        )
      )
    )
    .Sum()
  / 2500
) * 2500

WithName(
  RegexReplace(ref{columns/c-5Jgezs2B3o#funil_Contato;row;relative}, [literal], [literal]),
  ref{vars/NumeroLimpo;loop},
  If(
    ref{vars/NumeroLimpo;loop}.IsBlank(),
    [literal],
    If(
      ref{vars/NumeroLimpo;loop}.Len() < 8,
      [literal],
      WithName(
         /* =====================================================
           ETAPA 2 — GARANTE DDI
           ===================================================== */
        If(
          ref{vars/NumeroLimpo;loop}.StartsWith([literal]),
          ref{vars/NumeroLimpo;loop},
          Concatenate([literal], ref{vars/NumeroLimpo;loop})
        ),
        ref{vars/NumeroComDDI;loop},
        WithName(
           /* =====================================================
             ETAPA 3 — REMOVE DDI
             ===================================================== */
          ref{vars/NumeroComDDI;loop}.Right(ref{vars/NumeroComDDI;loop}.Len() - 2),
          ref{vars/NumeroSemDDI;loop},
               WithName(
               /* =====================================================
                 ETAPA 4 — GARANTE DDD (SÓ SE NÃO EXISTIR)
                 ===================================================== */
              If(
                ref{vars/NumeroSemDDI;loop}.Len() = 9,
                Concatenate([literal], ref{vars/NumeroSemDDI;loop}),
                ref{vars/NumeroSemDDI;loop}
              ),
              ref{vars/NumeroComDDD;loop},
              WithName(
                 /* =====================================================
                   ETAPA 5 — INSERE 9º DÍGITO (COM REGRAS)
                   ===================================================== */
                If(
                  AND(
                    ref{vars/NumeroComDDD;loop}.Len() = 10,
                    ref{vars/NumeroComDDD;loop}.Mid(3, 1) >= [literal],
                    ref{vars/NumeroComDDD;loop}.Mid(3, 1) <= [literal]
                  ),
                  Concatenate(
                    ref{vars/NumeroComDDD;loop}.Left(2), [literal], ref{vars/NumeroComDDD;loop}.Right(8)
                  ),
                  ref{vars/NumeroComDDD;loop}
                ),
                ref{vars/NumeroCelularCompleto;loop},
                 /* =====================================================
                   ETAPA 6 — VALIDA FINAL
                   ===================================================== */ IF(
                  OR(
                    AND(
                      ref{vars/NumeroCelularCompleto;loop}.Len() = 11,
                      ref{vars/NumeroCelularCompleto;loop}.Mid(3, 1) = [literal]
                    ),
                    ref{vars/NumeroCelularCompleto;loop}.Len() = 10
                  ),
                  Concatenate([literal], ref{vars/NumeroCelularCompleto;loop}),
                  [literal]
                )
              )

          )
        )
      )
    )
  )
)

