WithName(
  /* =====================================================
     ETAPA 1 — LIMPA O NÚMERO (SÓ DÍGITOS)
     ===================================================== */
  RegexReplace(ref{columns/c-87040HPZuy#Contato;row;relative}, [literal], [literal]),
  ref{vars/NumeroLimpo;loop},

  WithName(
    /* =====================================================
       ETAPA 2 — GARANTE DDI (55)
       ===================================================== */
    If(
      ref{vars/NumeroLimpo;loop}.StartsWith([literal]),
      ref{vars/NumeroLimpo;loop},
      Concatenate([literal], ref{vars/NumeroLimpo;loop})
    ),
    ref{vars/NumeroComDDI;loop},

    WithName(
      /* =====================================================
         ETAPA 3 — REMOVE DDI PARA TRATAR DDD + CELULAR
         ===================================================== */
      ref{vars/NumeroComDDI;loop}.Right(ref{vars/NumeroComDDI;loop}.Len() - 2),
      ref{vars/NumeroSemDDI;loop},

      WithName(
        /* =====================================================
           ETAPA 4 — GARANTE DDD (ASSUME 31 SE FALTAR)
           ===================================================== */
        If(
          ref{vars/NumeroSemDDI;loop}.Len() = 8 OR ref{vars/NumeroSemDDI;loop}.Len() = 9,
          Concatenate([literal], ref{vars/NumeroSemDDI;loop}),
          ref{vars/NumeroSemDDI;loop}
        ),
        ref{vars/NumeroComDDD;loop},

        WithName(
          /* =====================================================
             ETAPA 5 — GARANTE O 9º DÍGITO DO CELULAR
             ===================================================== */
          If(
            ref{vars/NumeroComDDD;loop}.Len() = 10,
            Concatenate(
              ref{vars/NumeroComDDD;loop}.Left(2),
              [literal],
              ref{vars/NumeroComDDD;loop}.Right(8)
            ),
            ref{vars/NumeroComDDD;loop}
          ),
          ref{vars/NumeroCelularCompleto;loop},

          /* =====================================================
             ETAPA 6 — VALIDA E FORMATA E.164
             ===================================================== */
          If(
            ref{vars/NumeroCelularCompleto;loop}.Len() = 11,
            Concatenate([literal], ref{vars/NumeroCelularCompleto;loop}),
            [literal]
          )
        )
      )
    )
  )
)

